{
  "tasks": [
    {
      "task_id": "T01",
      "title": "排除软件品类后按地区统计成本总和并取Top2",
      "business_question": "在排除“软件”品类的前提下，各地区的成本总和是多少？请仅保留成本最高的两个地区。",
      "priority": "P0",
      "priority_reason": "删除此任务将无法回答核心业务问题（比较非软件品类的地区成本）并支持相关决策。该任务直接对应所有核心约束：过滤条件、指标定义及排名限制。",
      "requirement_ids": [
       "C01",
       "C02",
       "C03",
       "C04"
      ],
      "depends_on": [],
      "missing_inputs": [],
      "steps": [
       {
       "step_id": "S01",
       "operation": "filter",
       "params": {
       "conditions": [
       {
       "field": "field_0003",
       "operator": "ne",
       "value": "软件"
       }
       ]
       }
       },
       {
       "step_id": "S02",
       "operation": "group_aggregate",
       "params": {
       "metrics": [
       {
       "function": "sum",
       "field": "field_0005",
       "alias": "cost_sum"
       }
       ],
       "dimensions": [
       "field_0002"
       ]
       }
       },
       {
       "step_id": "S03",
       "operation": "top_n",
       "params": {
       "field": "cost_sum",
       "direction": "desc",
       "n": 2
       }
       }
      ]
    }
  ]
}

{
  "tasks": [
    {
      "task_id": "T01",
      "title": "2025年已完成订单各品类销售额汇总",
      "business_question": "在仅分析2025年已完成订单且禁止分析成本的约束下，按品类汇总的销售额是多少？",
      "priority": "P0",
      "priority_reason": "直接回答核心业务目标：按品类汇总2025年已完成订单的销售额。删除此任务将无法完成主要分析需求。严格遵循“禁止分析成本”的限制，仅使用销售额字段。",
      "requirement_ids": [
       "C01",
       "C02",
       "C03",
       "C04",
       "C05"
      ],
      "depends_on": [],
      "missing_inputs": [],
      "steps": [
       {
       "step_id": "S01_1",
       "operation": "filter",
       "params": {
       "conditions": [
       {
       "field": "field_0001",
       "operator": "gte",
       "value": "2025-01-01"
       },
       {
       "field": "field_0001",
       "operator": "lt",
       "value": "2026-01-01"
       },
       {
       "field": "field_0006",
       "operator": "eq",
       "value": "已完成"
       }
       ]
       }
       },
       {
       "step_id": "S01_2",
       "operation": "group_aggregate",
       "params": {
       "metrics": [
       {
       "function": "sum",
       "field": "field_0004",
       "alias": "sales_sum"
       }
       ],
       "dimensions": [
       "field_0003"
       ]
       }
       }
      ]
    }
  ]
}

